-- 视图: project_stage_view
-- 返回每个项目的 4 个阶段(S1..S4)对应的月份区间 [startmonth, endmonth] (YYYYMM 整数)
--   - 有自定义配置(prj_stage_month_config)的项目: 直接使用配置
--   - 无配置的项目(含整12个月周期): 按 period_start_date 每三个月一阶段(与 StageMonthService.computeDefaultRanges 一致)
-- 供上游/下游流向按阶段聚合时 JOIN 使用。

create view project_stage_view as select project_id, stage_code, to_char(start_yyyymm,'FM999999') as startMonth, to_char(end_yyyymm,'FM999999') as endMonth from prj_stage_month_config union all select id, 'S1', to_char(period_start_date,'yyyyMM') as startMonth, to_char(to_date(to_char(period_start_date,'yyyyMM'),'yyyyMM') + interval '3 month' - interval '1 day', 'yyyyMM') as endMonth from prj_project where id not in (select distinct project_id from prj_stage_month_config) union all select id, 'S2', to_char(to_date(to_char(period_start_date,'yyyyMM'),'yyyyMM') + interval '3 month','yyyyMM') as startMonth, to_char(to_date(to_char(period_start_date,'yyyyMM'),'yyyyMM') + interval '6 month' - interval '1 day', 'yyyyMM') as endMonth from prj_project where id not in (select distinct project_id from prj_stage_month_config) union all select id, 'S3', to_char(to_date(to_char(period_start_date,'yyyyMM'),'yyyyMM') + interval '6 month','yyyyMM') as startMonth, to_char(to_date(to_char(period_start_date,'yyyyMM'),'yyyyMM') + interval '9 month' - interval '1 day', 'yyyyMM') as endMonth from prj_project where id not in (select distinct project_id from prj_stage_month_config) union all select id, 'S4', to_char(to_date(to_char(period_start_date,'yyyyMM'),'yyyyMM') + interval '9 month','yyyyMM') as startMonth, to_char(period_end_date,'yyyyMM') as endMonth from prj_project where id not in (select distinct project_id from prj_stage_month_config);
